def bubble(A):
    A, comps = A[:], 0
    for i in range(len(A) - 1):
        swapped = False
        for j in range(len(A) - 1 - i):
            comps += 1
            if A[j] > A[j + 1]:
                A[j], A[j + 1] = A[j + 1], A[j]
                swapped = True
        if not swapped:
            break
    return comps

def insertion(A):
    A, comps = A[:], 0
    for i in range(1, len(A)):
        key, j = A[i], i - 1
        while j >= 0:
            comps += 1
            if A[j] > key:
                A[j + 1] = A[j]
                j -= 1
            else:
                break
        A[j + 1] = key
    return comps

P = [2, 1, 3, 4, 6, 5]
print(bubble(P), insertion(P))
